<?php /* $contractRows contains administrator-only order/contract projections. */ ?>
<?php if(!$contractRows):empty_state('clock','Keine passenden Verträge','Passe die Filter an oder wähle einen anderen Kunden.');else: ?>
<div class="table-scroll"><table class="contract-table contract-table--contracts"><thead><tr><th>Kunde</th><th>Vertrag / Paket</th><th>Vertragsstatus</th><th>Preis / Zahlung</th><th>Laufzeit / Kündigung</th><th></th></tr></thead><tbody>
<?php foreach($contractRows as $contractRow): ?>
<tr data-contract-row="<?= (int)$contractRow['id'] ?>">
    <td data-label="Kunde"><a class="contract-customer" href="/admin/kunden?id=<?= (int)$contractRow['customer_id'] ?>"><strong><?= e(trim($contractRow['first_name'].' '.$contractRow['last_name'])) ?></strong></a><small><?= e($contractRow['email']) ?></small><small>Kunde #<?= (int)$contractRow['customer_id'] ?><?= $contractRow['company']?' · '.e($contractRow['company']):'' ?></small></td>
    <td data-label="Vertrag / Paket"><a class="text-link" href="/admin/vertraege?id=<?= (int)$contractRow['id'] ?>"><?= e($contractRow['reference']) ?></a><strong class="contract-product-name"><?= e($contractRow['product_name']) ?></strong><?php if($contractRow['domain']): ?><small><?= e($contractRow['domain']) ?></small><?php endif ?><small><?= $contractRow['parent_order_id']?'Zusatzmodul · zu Bestellung #'.(int)$contractRow['parent_order_id']:'Grundpaket / Einzelleistung' ?><?= $contractRow['deleted_ts']?' · Aus Bestellübersicht gelöscht':'' ?></small></td>
    <td data-label="Vertragsstatus"><?= admin_contract_badge($contractRow['admin_state']) ?><?php if($contractRow['needs_attention']): ?><small class="contract-attention"><?= icon('settings') ?> Bearbeitung erforderlich</small><?php endif ?></td>
    <td data-label="Preis / Zahlung"><strong><?= money($contractRow['amount_cents']) ?></strong><small>inkl. MwSt. / <?= cycle($contractRow['billing']) ?></small><small><?= e(admin_contract_payment_label($contractRow['payment_status'])) ?></small><?php if($contractRow['activated_ts'] && !in_array($contractRow['payment_status'],['paid','test_paid','no_charge'],true)): ?><small>Manuell freigegeben</small><?php endif ?></td>
    <td data-label="Laufzeit / Kündigung"><?php if($contractRow['cancel_at']): ?><strong>Ende: <?= admin_contract_timestamp($contractRow['cancel_at']) ?></strong><small>Eingang: <?= admin_contract_timestamp($contractRow['cancel_requested_at']) ?></small><?php elseif($contractRow['paid_until']): ?><strong>Bezahlt bis <?= admin_contract_timestamp($contractRow['paid_until']) ?></strong><small>Keine Kündigung vorgemerkt</small><?php else: ?><span><?= $contractRow['admin_state']==='pending'?'Noch nicht bestätigt':'Kein bezahlter Zeitraum hinterlegt' ?></span><?php endif ?></td>
    <td data-label="Aktionen"><div class="contract-row-actions"><a class="button button-outline button-small" href="/admin/vertraege?id=<?= (int)$contractRow['id'] ?>">Verwalten <?= icon('arrow') ?></a><?php if($contractRow['admin_state']==='cancellation' && !$contractRow['deleted_ts']): ?><a class="button button-outline button-small contract-end-now-link" data-contract-end-now href="/admin/vertraege?id=<?= (int)$contractRow['id'] ?>&amp;aktion=sofort-beenden#vertrag-sofort-beenden">Sofort kündigen</a><?php endif ?></div></td>
</tr>
<?php endforeach ?></tbody></table></div>
<?php endif ?>
